from pathlib import Path
from html import escape
import json, zipfile
root = Path(__file__).resolve().parent
frames = [
 {'id':'O02','title':'世界从门外经过','en':'The World Beyond the Door','file':'O02-countinghouse-v1.png','time':'开场 08–18 秒','focus':'晴蓝、生活细节、少年造型','start':'笔停在账本附近，左手碰到页角；门外的人和货物正在经过。','action':'翻页 → 核对门外货物 → 再次落笔，压住被风掀起的页角。'},
 {'id':'O03','title':'风压进屋里','en':'Wind at the Shutters','file':'O03-storm-v1.png','time':'开场 18–28 秒','focus':'身体重量、风向、风暴空间','start':'窗板仍开着，少年伸手抓住横档，重心准备向后。','action':'拉回窗板 → 插上木闩 → 退半步稳住，外界声音变闷。'},
 {'id':'O04','title':'这次写自己的话','en':'His Own Words','file':'O04-writing-v1.png','time':'开场 28–40 秒','focus':'暗部层次、烛光、脸与双手','start':'风灾后的夜里，纸面尚空，少年准备落下第一笔。','action':'落笔 → 写一小段 → 停顿 → 继续。'},
 {'id':'E3-02','title':'共同署名','en':'Signing Together','file':'E3-02-shared-signature-v1.png','time':'合作结局 08–16 秒 · 剧情提案','focus':'成年身份、双人构图、轮流行动','start':'Hamilton 执笔，伯尔等待，两人注意力在同一份文件上。','action':'完成一笔 → 放笔 → 推纸 → 伯尔伸手接笔。'},
 {'id':'C01','title':'记录仍在继续','en':'The Record Continues','file':'C01-eliza-chronicler-v1.png','time':'结尾通用镜头 24–30 秒','focus':'浅蓝裙、完全隐于阴影的脸、记录姿态','start':'Eliza 低头，执笔与打开的记录册，手触页角。','action':'停顿 → 落笔或按住来信 → 风轻触页角；不抬头露出五官。'}
]
articles=[]
for i,f in enumerate(frames):
 p=root/'images'/f['file']; assert p.exists(), p
 image=f'images/{f["file"]}'
 articles.append(f'''<article id="{f['id']}" class="{'hero' if i==0 else ''}"><a class="image" href="{image}" target="_blank"><img src="{image}" alt="{escape(f['title'])}" {'loading="lazy"' if i else ''}></a><div class="copy"><div class="meta">{f['id']} / {f['time']}</div><h2>{f['title']}</h2><div class="english">{f['en']}</div><p class="focus">{f['focus']}</p><p><b>首帧</b> {f['start']}</p><p><b>随后</b> {f['action']}</p><a class="prompt" href="prompts/{f['id']}.txt" target="_blank">查看生成提示词 ↗</a></div></article>''')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hamilton · 纸上史诗首帧定调</title><style>
:root{--paper:#efeade;--ink:#203742;--muted:#63716e;--gold:#9a6942}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.7 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}main{max-width:1500px;margin:auto;padding:54px 34px}header{display:flex;align-items:end;justify-content:space-between;gap:30px;border-bottom:1px solid #c2c4b8;padding-bottom:28px;margin-bottom:30px}.eyebrow{font-size:12px;letter-spacing:.18em;color:var(--gold)}h1{font:600 clamp(34px,5vw,64px)/1.1 serif;margin:15px 0}header p{max-width:670px;color:var(--muted)}.tag{font-size:12px;border:1px solid #a9b5ae;border-radius:20px;padding:6px 12px;white-space:nowrap}a{color:var(--gold);text-decoration-thickness:1px;text-underline-offset:4px}.links{display:flex;gap:24px;flex-wrap:wrap;margin:24px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.hero{grid-column:1/-1;display:grid;grid-template-columns:2.2fr 1fr;align-items:center}article{background:#f8f5ec;border:1px solid #d2d6c8;overflow:hidden}article .image{display:block}article img{width:100%;display:block;aspect-ratio:16/9;object-fit:contain;background:#172c35}.copy{padding:24px 27px}.meta{font-size:11px;letter-spacing:.06em;color:var(--gold)}h2{font:600 28px/1.3 serif;margin:9px 0 0}.english{font-family:Georgia,serif;font-size:15px;color:var(--muted)}p{margin:12px 0}.copy p{font-size:14px;color:#52635f}.copy b{color:var(--ink);margin-right:7px}.focus{border-bottom:1px solid #d5d8cc;padding-bottom:13px}.prompt{font-size:12px}.section{margin:42px 0;padding:25px 30px;background:#e4e6db}.section h2{font-size:24px}.chain{display:flex;flex-wrap:wrap;gap:12px;margin:15px 0}.chain span{padding:9px 14px;background:#f8f5ec;border:1px solid #cbd0c2;font-size:14px}.section p{color:#536960}.foot{border-top:1px solid #bdc4b8;padding-top:20px;font-size:13px;color:var(--muted)}@media(max-width:1000px){.hero{display:block}}@media(max-width:680px){main{padding:25px 16px}header{display:block}.grid{grid-template-columns:1fr}.hero{grid-column:auto}.copy{padding:20px}.tag{display:inline-block}}
</style><main><header><div><div class="eyebrow">HAMILTON · AN EPIC ON PAPER · 2026.10.28</div><h1>纸上史诗</h1><p>同一部动画电影的五张首帧。细线人物、水彩／水粉背景、柔和纸纹与电影光影，从晴日走进风暴，再回到纸面与人的关系。</p></div><span class="tag">第一轮定调 · 5 张静帧</span></header><nav class="links"><a href="视频脚本与首帧清单.md">完整视频脚本</a><a href="Hamilton-纸上史诗-首帧定调-v1.zip" download>下载图片、脚本与提示词</a><a href="https://xhslink.cn/o/2VrlNG2jIyq">回看原始参考视频</a><a href="generation-manifest.json">生成与验收记录</a></nav><div class="grid">'''+''.join(articles)+'''</div><section class="section"><h2>开场 · 被读到的那一页</h2><p>The Page Someone Read · 60 秒脚本草案</p><div class="chain"><span>00–08s 空下的位置</span><span>08–18s 商行劳动</span><span>18–28s 风灾</span><span>28–40s 灾后写作</span><span>40–50s 被读到与获得帮助</span><span>50–60s 离岛</span></div><p>结局各写成 3 个专属镜头与 1 个记录者镜头，共 30 秒。五结局仍以既有策划提案为基础，本轮用于审阅画面和叙事。</p></section><section class="section"><h2>这轮主要看什么</h2><p>人物是否足够成熟、纸纹是否合适、日夜是否属于同一画法、每张首帧是否能够自然展开动作。动态中的脸、手、羽毛笔和纸张稳定性仍需要后续视频样片验证。</p></section><footer class="foot">使用内置 imagegen 生成，输出保留原始 PNG。无对白、旁白或烘焙字幕；本轮为视频脚本和首帧样稿，尚未生成动画或接入游戏。<p>剧情事件 → 单镜头起势与动作 → 首帧定调 → 动作样片 → 完整 CG。</p></footer></main></html>'''
(root/'index.html').write_text(page)
(root/'frame-index.json').write_text(json.dumps(frames,ensure_ascii=False,indent=2))
with zipfile.ZipFile(root/'Hamilton-纸上史诗-首帧定调-v1.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted(root.rglob('*')):
  if p.is_file() and p.suffix in ['.png','.txt','.md','.html','.json']:
   z.write(p,p.relative_to(root))
print(root/'index.html')
print('Bundled',len(frames),'frames with scripts and prompts.')
